'use client'

import * as React from 'react'

import { Button } from './button'
import { ChevronGlyph } from './glyphs'
import { useStrings, type StringsOverrides } from './strings'

import './page-header.css'
import './gamestage-primitives.css'

export interface PageHeaderProps extends Omit<React.HTMLAttributes<HTMLElement>, 'children' | 'title'> {
  /** The page's title, supplied by the host. */
  title: string
  /** The game or event this page belongs to, read with the title. */
  heading?: string
  /** The host's event and sponsor lockup. */
  brand?: React.ReactNode
  /** Reports a back press. The host decides what happens next. */
  onBack?: () => void
  backLabel?: string
  /** Plain words or the tertiary button. Unset, the theme chooses. */
  backPresentation?: 'button' | 'link'
  /** Use 2 when the host already supplies the page's main heading. */
  level?: 1 | 2
  /** Per-instance vocabulary, merged over the provider. */
  strings?: StringsOverrides
}

/** The host's lockup, the page's name and an optional way back. Performs nothing. */
export function PageHeader({
  title,
  heading,
  brand,
  onBack,
  backLabel,
  backPresentation,
  level = 1,
  strings,
  className,
  ...rest
}: PageHeaderProps) {
  const copy = useStrings(strings)
  const Title = level === 2 ? 'h2' : 'h1'

  return (
    <header {...rest} className={['gs-page-header', className].filter(Boolean).join(' ')} data-gs-component="page-header">
      {brand != null ? (
        <div className="gs-page-header__brand" data-gs-scope="page-header" data-gs-part="brand">
          {brand}
        </div>
      ) : null}
      <Title className="gs-page-header__title">
        {heading ? (
          <>
            <span className="gs-page-header__heading" data-gs-scope="page-header" data-gs-part="heading">{heading}</span>
            {' '}
          </>
        ) : null}
        <span data-gs-scope="page-header" data-gs-part="label">{title}</span>
      </Title>
      {onBack ? (
        <Button
          variant="tertiary"
          className="gs-page-header__back"
          data-gs-scope="page-header"
          data-gs-part="back"
          data-gs-presentation={backPresentation}
          onClick={() => onBack()}
        >
          <span className="gs-page-header__back-content">
            <span className="gs-page-header__chevron" data-gs-scope="page-header" data-gs-part="chevron" aria-hidden="true">
              <ChevronGlyph direction="left" />
            </span>
            <span>{backLabel ?? copy['page-header.backLabel']}</span>
          </span>
        </Button>
      ) : null}
    </header>
  )
}

/* The host supplies the lockup. Type, spacing and controls follow the theme. */
.gs-page-header {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--gs-space-gap);
  inline-size: 100%;
  min-inline-size: 0;
  color: var(--gs-color-ink);
  overflow-wrap: anywhere;
}

.gs-page-header__brand {
  box-sizing: border-box;
  inline-size: var(--gs-page-header-brand-width, auto);
  text-align: var(--gs-page-header-align, inherit);
  padding-block: var(--gs-page-header-padding-block, 0px);
  padding-inline: var(--gs-page-header-padding-inline, 0px);
  background: var(--gs-page-header-surface, transparent);
  border-block-end: var(--gs-page-header-rule-width, 0px) solid var(--gs-page-header-rule-colour, transparent);
  min-inline-size: 0;
  max-inline-size: 100%;
}

.gs-page-header__brand img,
.gs-page-header__brand svg {
  display: block;
  margin-inline: var(--gs-page-header-brand-margin, 0);
  max-inline-size: 100%;
  block-size: auto;
}

.gs-page-header__title {
  display: flex;
  flex-direction: column;
  gap: var(--gs-space-1);
  inline-size: 100%;
  min-inline-size: 0;
  margin: 0;
  font-family: var(--gs-type-title-font-family);
  font-size: var(--gs-type-title-font-size);
  font-weight: var(--gs-type-title-font-weight);
  line-height: var(--gs-type-title-line-height);
}

.gs-page-header__heading {
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  line-height: var(--gs-type-title-line-height);
  color: var(--gs-color-ink-secondary);
}

.gs-page-header__back {
  box-sizing: border-box;
  max-inline-size: 100%;
}

.gs-page-header__back-content {
  display: flex;
  align-items: center;
  gap: var(--gs-space-2);
  min-inline-size: 0;
}

.gs-page-header__chevron {
  display: inline-flex;
  flex: none;
  font-size: var(--gs-page-header-back-icon-size, inherit);
  inline-size: var(--gs-page-header-back-icon-size, var(--gs-size-icon-utility));
  block-size: var(--gs-page-header-back-icon-size, var(--gs-size-icon-utility));
}

/* A plain back action keeps Button's target, focus and press feedback. */
.gs-page-header .gs-page-header__back[data-gs-presentation="link"],
.gs-page-header .gs-page-header__back[data-gs-presentation="link"]:hover,
.gs-page-header .gs-page-header__back[data-gs-presentation="link"]:active {
  padding-inline: 0;
  color: var(--gs-page-header-back-ink, var(--gs-color-ink));
  background: transparent;
  border: 0;
  border-radius: 0;
  box-shadow: none;
  font-family: var(--gs-type-body-font-family);
  font-size: var(--gs-page-header-back-size, var(--gs-type-body-font-size));
  font-weight: var(--gs-type-body-font-weight);
  line-height: var(--gs-type-body-line-height);
  letter-spacing: normal;
  text-transform: none;
}
